"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "指数计算错误"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "独立重复试验用伯努利公式。记住P(X=k)=C(n,k)*p^k*(1-p)^(n-k)。"}]}]}]}$$ AS jsonb), NULL, '数量关系-概率问题-独立重复试验的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "概率问题", "独立重复试验"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_prob_repeat", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
